const startHtml5ScannerWithFallback = async (
  html5QrCode: Html5Qrcode,
  config: any,
  onSuccess: (text: string) => void,
  onError: (err: string) => void,
  preferredFacingMode: 'environment' | 'user' = 'environment'
) => {
  try {
    const devices = await Html5Qrcode.getCameras().catch(() => []);
    if (devices && devices.length > 0) {
      const targetDevice = devices.find(device => {
        const label = (device.label || '').toLowerCase();
        if (preferredFacingMode === 'environment') {
          return label.includes('back') || label.includes('environment') || label.includes('rear') || label.includes('world');
        } else {
          return label.includes('front') || label.includes('user') || label.includes('selfie');
        }
      });
      const cameraId = targetDevice ? targetDevice.id : devices[0].id;
      console.log(`Starting scanner with camera ID: ${cameraId} (${targetDevice ? targetDevice.label : 'default'})`);
      await html5QrCode.start(cameraId, config, onSuccess, onError);
      return;
    }
  } catch (e) {
    console.warn("Failed to get cameras, falling back to facingMode constraint:", e);
  }

  try {
    console.log(`Starting scanner with facingMode constraint: ${preferredFacingMode}`);
    await html5QrCode.start({ facingMode: preferredFacingMode }, config, onSuccess, onError);
  } catch (err1) {
    console.warn(`Failed to start with facingMode ${preferredFacingMode}, retrying with opposite...`, err1);
    const oppositeMode = preferredFacingMode === 'environment' ? 'user' : 'environment';
    try {
      await html5QrCode.start({ facingMode: oppositeMode }, config, onSuccess, onError);
    } catch (err2) {
      console.warn(`Failed to start with facingMode ${oppositeMode}, retrying without constraint...`, err2);
      try {
        await html5QrCode.start({} as any, config, onSuccess, onError);
      } catch (err3) {
        console.error("All QR scanner start attempts failed:", err3);
        throw err3;
      }
    }
  }
};

