const playBeep = () => {
  try {
    const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
    const oscillator = audioContext.createOscillator();
    const gainNode = audioContext.createGain();

    oscillator.connect(gainNode);
    gainNode.connect(audioContext.destination);

    oscillator.type = 'sine';
    oscillator.frequency.setValueAtTime(800, audioContext.currentTime);
    gainNode.gain.setValueAtTime(0, audioContext.currentTime);
    gainNode.gain.linearRampToValueAtTime(0.5, audioContext.currentTime + 0.01);
    gainNode.gain.linearRampToValueAtTime(0, audioContext.currentTime + 0.2);

    oscillator.start(audioContext.currentTime);
    oscillator.stop(audioContext.currentTime + 0.2);

    if (audioContext.state === 'suspended') {
      audioContext.resume();
    }
  } catch (error) {
    console.warn('Audio beep failed:', error);
  }
};

const Card = ({ children, className = "", ...props }: { children: React.ReactNode, className?: string, [key: string]: any }) => {
  const hasBg = className.includes('bg-');
  return (
    <div className={`${!hasBg ? 'bg-white' : ''} rounded-2xl p-4 sm:p-6 md:p-8 border border-slate-100 shadow-[0_10px_30px_rgba(0,0,0,0.05)] ${className}`} {...props}>
      {children}
    </div>
  );
};

const openWhatsAppLink = (phone: string, text: string) => {
  const cleanMobile = (phone || '').replace(/\D/g, '');
  const formattedPhone = cleanMobile ? (cleanMobile.length === 10 ? '91' + cleanMobile : cleanMobile) : '';
  const encodedText = encodeURIComponent(text);
  
  // Directly open WhatsApp Web send URL which uses browser local session storage
  // Once logged in once with 'Stay logged in on this browser', WhatsApp Web will open immediately without asking to log in again
  const webUrl = formattedPhone 
    ? `https://web.whatsapp.com/send?phone=${formattedPhone}&text=${encodedText}`
    : `https://web.whatsapp.com/send?text=${encodedText}`;
    
  window.open(webUrl, '_blank');
};

const shareAttendanceOnWhatsApp = async (student: any, record: any, schoolProfile?: any) => {
  if (!student) return;
  const mobile = student.fatherMobile || student.motherMobile || student.emergencyContact;
  if (!mobile) {
    alert("Mobile number not found for this student's parents.");
    return;
  }
  
  const message = `*Attendance Alert - ${schoolProfile?.name || 'School'}*\n\nDear Parent,\nThis is to inform you that *${student.name} ${student.surname}* (${student.studentId}) is marked *${record.status}* for today (${formatDate(record.date)}).\n\nTime: ${record.time || '--:--'}\nStatus: ${record.status}\n\nRegards,\nSchool Administration`;
  const cleanMobile = mobile.replace(/\D/g, '');

  try {
    const statusRes = await fetch("/api/whatsapp/status");
    const statusData = await statusRes.json();
    if (statusData && statusData.status === "Connected") {
      const sendRes = await fetch("/api/whatsapp/send-message", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ phone: cleanMobile, message })
      });
      const sendData = await sendRes.json();
      if (sendData.success) {
        alert(`Attendance WhatsApp alert sent automatically via ${statusData.mode === "Meta" ? "Meta Cloud API" : "WhatsApp Gateway"}!`);
        return;
      }
    }
  } catch (e) {
    console.error("[WhatsApp Attendance Send] Failed, falling back to manual link:", e);
  }

  openWhatsAppLink(cleanMobile, message);
};

