const shareFeeOnWhatsApp = async (t: any, students: Student[], schoolProfile: any) => {
    const student = students.find(s => s.studentId === t.studentId);
    if (!student) return;
    const cleanMobile = (student.fatherMobile || student.motherMobile || student.emergencyContact || '').replace(/\D/g, '');
    if (!cleanMobile) {
      alert("Mobile number not found for this student.");
      return;
    }
    
    let text = `*Fee Receipt - ${schoolProfile.name}*\n\nDear Parent,\nWe have received your payment of *₹${t.amount.toLocaleString()}* for ward *${student.name} ${student.surname}* (${student.studentId}).\n\n*Transaction Details:*\nReceipt No: ${t.id || 'N/A'}\nDate: ${formatDate(t.date)}\nType: ${t.type}\nStatus: ${t.status}\n\nThank you for your timely payment.`;
    
    if (t.type === 'Due Reminder') {
      text = `*Fee Reminder - ${schoolProfile.name}*\n\nDear Parent,\nThis is a reminder regarding the pending fees for your ward *${student.name} ${student.surname}* (${student.studentId}).\n\n*Pending Amount: ₹${t.amount.toLocaleString()}*\n\nPlease clear the dues at the earliest. Ignore if already paid.\n\nThank you.`;
    }

    try {
      const statusRes = await fetch("/api/whatsapp/status");
      const statusData = await statusRes.json();
      if (statusData && statusData.status === "Connected") {
        const sendRes = await fetch("/api/whatsapp/send-message", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ phone: cleanMobile, message: text })
        });
        const sendData = await sendRes.json();
        if (sendData.success) {
          alert(`WhatsApp notification sent successfully via ${statusData.mode === "Meta" ? "Meta Cloud API" : "WhatsApp Gateway"}!`);
          return;
        }
      }
    } catch (e) {
      console.error("[WhatsApp Fee Send] Failed, falling back to manual link:", e);
    }

    openWhatsAppLink(cleanMobile, text);
};

const formatDate = (date: Date | string) => {
  if (!date) return '-';
  const d = new Date(date);
  if (isNaN(d.getTime())) return String(date);
  const day = String(d.getDate()).padStart(2, '0');
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const year = d.getFullYear();
  return `${day}/${month}/${year}`;
};

